INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Miniblox', 'A multiplayer voxel game that was released all the way back in February 2022 under BlockCraft. Gamemodes are Survival, Creatve, Skyblock, and Oneblock as sandbox ones. KitPvP, Skywars, Eggwars, and Murder Mystery are ones which involve attacking each other to win! Blitz Build involve building the same replica build as the game build to win a game, while Spleef is simply the classic mode of Spleef. Other gamemodes are Block Hunt (Hide & Seek), Bridge Duels, Parkour, One in the Quiver, and Classic PVP.' FROM games WHERE igdb_id = 384485 ON CONFLICT (game_id, language_code) DO NOTHING;
