INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sky Fighters', 'A top-down, fast-paced shooter where you pilot a plane and use it to dogfight against those that seek to bring you down. Easy to understand but hard to master, the balance of risk-reward for score maximization while trying to not get overwhelmed is what this game is about! Try to reach to the highest score!' FROM games WHERE igdb_id = 275664 ON CONFLICT (game_id, language_code) DO NOTHING;
