INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pure-mini-golf', 188100, '2022-01-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5avb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1e07.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pure Mini Golf', 'Enjoy over 50 unique levels, each with its own set of obstacles, twists, and turns. Its simple controls make it a snap to learn from the outset and through its three modes, you’ll soon go from fledgling to master putter. Arcade mode takes you through the game’s levels where you can play at your own pace. Once you’re feeling more confident in your skills, you can take on Challenge mode where failing at any time takes you back to the beginning. And when you’re done playing alone, you can bring in up to three friends for some Local Multiplayer and chill. The putting life is a simple one. Bring it into your home with Pure Mini Golf.' FROM games WHERE igdb_id = 188100 ON CONFLICT (game_id, language_code) DO NOTHING;
