INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Hauntings: Surveillance', 'Welcome to the Directive Seven Bravo surveillance team. There''s an office that''s been experiencing paranormal events. Your task is to scan through various cameras set up throughout the building and document as many activities as possible. Be warned: this assignment is of high importance and If you miss too many activities, or report improper activities, you will be fired.' FROM games WHERE igdb_id = 202367 ON CONFLICT (game_id, language_code) DO NOTHING;
