INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mechasaur vs Punchatron', 'Take on the role of Mechasaur, a kaiju turned war machine that has escaped from the labs and is running loose through the city. The only thing stopping you from razing the entire city to the ground is Punchatron, the giant robot that originally captured you.' FROM games WHERE igdb_id = 364744 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 364744 AND p.igdb_id = 6 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('psychonauts-2-motherlobe-edition', 207394, '2022-10-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5fb6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1q52.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Psychonauts 2: Motherlobe Edition', 'Psychonauts 2: Motherlobe Edition is a physical release of the 2021 platform-adventure game developed by Double Fine Productions. It includes the full game along with a lenticular o-sleeve, a reversible poster, and a set of six art cards. The edition also features digital download codes for behind-the-scenes materials such as concept art and developer commentary. Gameplay remains unchanged, combining platforming, exploration, and psychic abilities across story-driven levels.' FROM games WHERE igdb_id = 207394 ON CONFLICT (game_id, language_code) DO NOTHING;
