INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mayapan', 'Conquer the great pyramid of Mayapan by showing your point and shoot skills. Match colors and make use of special bonuses. Feeling good? Try the Survival chamber, at the pyramid''s lower level. Resist as long as you can.. or taste the heated lava! Compete with other Oculus players in the general leaderboard! Be the best!' FROM games WHERE igdb_id = 198408 ON CONFLICT (game_id, language_code) DO NOTHING;
