INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adios Amigos: Galactic Explorers', 'Team up with your friends & family and explore the peculiar universe of ADIOS Amigos. A game with serious astrophysics in a comic setting for 1-4 players. Explore solar systems and discover planets, space stations, aliens, and artifacts. Improvise fuel efficient trajectories to keep your rusty ship running (and you might see your home planet once again). Toy with accurate and delightful space physics. Break into a space station with an asteroid. Tow a sofa into a black hole. Normal stuff.' FROM games WHERE igdb_id = 197685 ON CONFLICT (game_id, language_code) DO NOTHING;
