INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Purgatory Dungeoneer', 'A roguelite RPG about plundering a psychic hellmaw for personal closure, and the resources to build a town beyond the grave. Become the mayor of a supernatural medieval village. Recruit over 400 former adventurers to plunder the hellmaw for resources, and unlock the buried memories of your companions. Use these resources to improve the village, and the capabilities of your citizens. And strive to keep a personal touch as the village grows beyond your expectations.' FROM games WHERE igdb_id = 202581 ON CONFLICT (game_id, language_code) DO NOTHING;
