INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shining Gadget', 'Shining Gadget is a passive creature collecting idle game that transforms your Playdate into an online-enabled specter catcher! Take aim at ghosts and suck them into your Playdate using the built-in crank! Keep your tractor beam on target to weaken the ghost and crank for maximum pull! Your precision and reflexes will be put to the ultimate test as you collect ancient and powerful spirits!' FROM games WHERE igdb_id = 221078 ON CONFLICT (game_id, language_code) DO NOTHING;
