INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wyoming Winter', '"Wyoming Winter" is a multiplayer horror game where players must survive against a powerful, fast-moving creature called the Blight. Players can find weapons through completing a checklist to prevent the Blight from escaping the facility. The game is best played with 3-8 players, and servers are available in Europe, America, and Asia.' FROM games WHERE igdb_id = 228807 ON CONFLICT (game_id, language_code) DO NOTHING;
