INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('symphony-of-motion', 321236, '2022-06-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co900j.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar38b9.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Symphony Of Motion', 'Symphony Of Motion offers a new unique way to create and experience music without the need for any prior musical knowledge. Whether you''re a seasoned musician or a complete beginner, this is a new and intuitive way to create and experience music. In its simplest form, you just move your hands around to create unique sounds, melodies, and rhythms. There are no “wrong” notes to worry about (as you always play in a specific scale) and you can always stay on perfect tempo with the build-in perfect timing assistant. For the more experienced musicians, it also offers a lot of customization options, a build-in looper, and new levels of expressional depth with its three-dimensional motion modulation, live pitch-shifting drums, and melodic pads.' FROM games WHERE igdb_id = 321236 ON CONFLICT (game_id, language_code) DO NOTHING;
