INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Morbsweeper', 'Play as Dr. Michael Morbius, and suck your way to victory! This is a twisted version of MINESWEEPER. Click on a MORB to reveal what is underneath. BE CAREFUL. Some MORBS have a REVIEW BOMB under them, which will damage your Tomatometer score. AVOID THESE AT ALL COSTS! If you see a tile with a number, that means it''s touching that many REVIEW BOMBS. Click carefully!' FROM games WHERE igdb_id = 210368 ON CONFLICT (game_id, language_code) DO NOTHING;
