INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Little Pony: A Maretime Bay Adventure', 'Only you can help Sunny throw the most magical celebration Equestria has ever seen in the adventure game My Little Pony: A Maretime Bay Adventure. Use your magic to put on fashion shows, find the cutest animals, fly with the Pegasi and more. Customize your ponies by unlocking new skills and accessories, including new hats and jewelry, rollerblades, and fashion magic. Your friends Hitch, Izzy, Zipp and Pipp are here to lend a helping hoof every step of the way. And you can invite another player for multiplayer minigames!' FROM games WHERE igdb_id = 191956 ON CONFLICT (game_id, language_code) DO NOTHING;
