INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blown Away', 'Blown Away is a puzzle platformer that lets you explore the world of Yhorba. Let Mylo take you on an adventure and help him solve puzzles and save the island. In these puzzles you need to find certain parts that will help Mylo and the island of Yhorba to restore peace. Are you in for a new journey?' FROM games WHERE igdb_id = 187703 ON CONFLICT (game_id, language_code) DO NOTHING;
