INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paragon Pioneers', 'Paragon Pioneers is a city-building idle game in which you discover, conquer and then build on islands to fulfill the needs of your inhabitants. Even with limited time to play you can enjoy this deep simulation game and follow one of the countless ways to optimize your empire. Build an impressive palace and go down in history as Paragon''s most successful leader.' FROM games WHERE igdb_id = 206351 ON CONFLICT (game_id, language_code) DO NOTHING;
