INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tailbound', 'Tailbound is a lewd top-down 2D hack n'' slash game. The game features Zelda-like gameplay, but at a far faster pace and with more of a focus on abilities and level hazards. Gameplay is based around an improved version of Thirstchasm''s topple system & combat.
