INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Autobahn Police Simulator 2: Switch Edition', 'An exciting career awaits you In Autobahn Police Simulator 2 for Nintendo Switch. Patrolling the German autobahns – arguably Europe’s busiest roads- is not for the fainthearted as you battle to maintain speed restrictions, track down drugs traffickers and manage road traffic incidents.' FROM games WHERE igdb_id = 178766 ON CONFLICT (game_id, language_code) DO NOTHING;
