INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Light & Shadow', 'When a star falls in a nearby forest, it spurs Po onto a quest to find that light and bring it into their life. Light & Shadow is a shadow puppet platformer where you face your anxieties, push past depression, and seek moments of joy in a grey world. Finding your way isn''t always easy, keep going!' FROM games WHERE igdb_id = 226425 ON CONFLICT (game_id, language_code) DO NOTHING;
