INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'HooperVania', 'Welcome to HooperVania, a free and non-profit French fan game celebrating Castlevania, the French videomaker Hooper, his community, and video games as a whole! Navigate through various stages using the famous Vampire Killer to defeat numerous enemies, and large bosses and ultimately vanquish Dracula himself!' FROM games WHERE igdb_id = 265859 ON CONFLICT (game_id, language_code) DO NOTHING;
