INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'As Long As It''s Not Illegal: Act I', 'It''s Friday night, you and the other Senior Elites devise a plan to throw a party at the rival campus. Carpool across Suncity limits, down into the lawless land of the Undercity. It''s Illegal for these two cities to mingle. But is it illegal if... you''re never caught?' FROM games WHERE igdb_id = 230322 ON CONFLICT (game_id, language_code) DO NOTHING;
