INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teleportal', 'This is a side-scrolling puzzle action game with a swapping theme. The selling points of this game are the fast-paced action that comes from swapping, the exhilaration of using swaps to think one or two moves ahead to solve puzzles, and the new fighting style that utilizes the environment, such as the protagonist being unable to attack enemies, but switching places with them when they fire bullets and defeating them with their own bullets.' FROM games WHERE igdb_id = 380850 ON CONFLICT (game_id, language_code) DO NOTHING;
