INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castle Renovator', 'Build your own kingdom and customize it to your liking. You start on your own inherited piece of land. Work as a craftsman to clean, repair, build and decorate medieval, renaissance and baroque buildings and castles. Visit beautiful locations, breathe new life into old rooms and as you know - hard work pays off - so maybe one day you will become the King?' FROM games WHERE igdb_id = 219174 ON CONFLICT (game_id, language_code) DO NOTHING;
