INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Coffee Break: A Sip Away from Doom', 'In a tedious day, Oliver finishes his best invention yet: A SubAtomic coffee machine that is to make the perfect coffee. But a problem emerged when the perfect coffee was so good it blew up the machine and ruptured timespace. Now, Oliver has to retrieve the pieces of his machine that are scattered through the multiverse. Follow Oliver in his adventure through the dimensions in search of the perfect coffee! Meet various worlds with incredible art, charismatic characters and challenging puzzles!' FROM games WHERE igdb_id = 213577 ON CONFLICT (game_id, language_code) DO NOTHING;
