INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rogue Ascent VR', 'Rogue Ascent VR is an upcoming experimental Procedurally-Generated Sci-Fi Shooter controlled seamlessly by Oculus hand-tracking technology. Discover and combine countless weapons types, attachment modifications, abilities, gadgets, perks, and powerups as you blast and beguile past teams of formidable foes. The completed gameplay experience will feature many added items, secrets, perks, abilities, enemy types, game modes, bosses, biomes, achievements, and competitive online leaderboards for you to challenge your friends (or rivals!).' FROM games WHERE igdb_id = 191914 ON CONFLICT (game_id, language_code) DO NOTHING;
