INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Grandparents'' Christmas Mystery', 'Grandma never showed up and Grandpa''s tragic passing 3 days later left me in anger, confusion and sadness. I couldn''t just let this go like it never happened, so I decided to go and find out what happened on my own. Will you survive a first-person psychological horror game and uncover the mystery?' FROM games WHERE igdb_id = 236378 ON CONFLICT (game_id, language_code) DO NOTHING;
