INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yomawari: Lost in the Dark - Deluxe Edition', 'A young girl awakens in a dark, unfamiliar forest with no recollection of how she got there. As she searches for a way out, she crosses paths with a mysterious individual who reveals to her that she’s been cursed. In order to break the curse, she needs to explore the streets of her town at night to seek out her lost memories. However, malevolent ghosts lurk within the shadows, and the girl must avoid them by running, hiding, and shutting her eyes if she hopes to survive long enough to break her curse.' FROM games WHERE igdb_id = 203095 ON CONFLICT (game_id, language_code) DO NOTHING;
