INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SuperVHS', 'A mildly famous warehouse lurks somewhere deep in Milwaukee, Wisconsin. Hidden by relentless snow (or possibly that technology from 1994''s The Shadow), spoken of only under whispered breath. Legends of sets, props, and bad movies as far as the eye can see. No one has returned from this place in a thousand years. No one...until now!' FROM games WHERE igdb_id = 213268 ON CONFLICT (game_id, language_code) DO NOTHING;
