INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('animalia-dreamland', 242150, '2022-06-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co69x6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sclr7g.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Animalia Dreamland', 'Animalia Dreamland is a small single-screen platformer for the NES. In each level you play as one of two randomly selected animals, with randomized physics. For "Three Dreams" mode you play a random three of the 17 base levels, while for "Full Game" mode you play these 17 levels, in order, followed by a final 18th level. Pressing Select on the title screen toggles "Lucid Mode", where you choose your preferred jump physics.' FROM games WHERE igdb_id = 242150 ON CONFLICT (game_id, language_code) DO NOTHING;
