INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Curse of Eclipse', 'This is an adventure and puzzle game inspired by old school games of 1980s like Atic Atac from ZX Spectrum. You walk in a cursed house avoiding enemies and finding keys and magical scrolls. The game is playable with 3rd person, 1st person and top down views. Created by a solo developer.' FROM games WHERE igdb_id = 235807 ON CONFLICT (game_id, language_code) DO NOTHING;
