INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('melody-before-the-dawn', 367404, '2022-03-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coagv6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4vqw.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Melody before the Dawn', 'Celica, a young girl living in the far north, finds herself every night stepping into another world through her dreams—one filled with sights she has never seen, vibrant companions, and a miraculous encounter. Yet as tender feelings begin to awaken, she is reminded that it is nothing more than an illusion… What is the connection between dream and reality, and how will their destinies change? Shrouded in mist, she spreads the wings of her dream and sings for the coming dawn.' FROM games WHERE igdb_id = 367404 ON CONFLICT (game_id, language_code) DO NOTHING;
