INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brendan Keogh''s Putting Challenge', 'Brendan Keogh’s Putting Challenge is a local co-op golf game about all the parts other golf videogames cut out. Sounds tedious? It sort of is. Bring your friends! With up to four players on a single device, you have complete freedom to explore the massive open-world at your own pace with your friends. Play a round of mini-golf, compete on a full 9 hole course, go for a bike ride or just see who can hit the ball the furthest at the driving range. It’s entirely up to you.' FROM games WHERE igdb_id = 191444 ON CONFLICT (game_id, language_code) DO NOTHING;
