INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega', 'This is a short story about humanity''s last attempt to resist nature. Cities lie in ruins, there are traces of huge claws everywhere - once disturbed by people, giants began to wreak havoc around the world. But is there a solution?' FROM games WHERE igdb_id = 215615 ON CONFLICT (game_id, language_code) DO NOTHING;
