INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Impasto', 'Impasto is a first-person horror adventure game inspired by the works and legacy of Francisco Goya, the revered yet tortured Spanish painter. Set within a world irreversibly altered by his fraying sanity, the player must use both stealth and wits to survive.' FROM games WHERE igdb_id = 201896 ON CONFLICT (game_id, language_code) DO NOTHING;
