INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tyrant''s Blessing', 'Tyrant''s Blessing is a tactical turn-based game where your ability to plan, adapt, and strategize is more important than min-maxing your units or finding the sharpest sword in the hoard. Select battles every day, make challenging choices, and cleverly use the strengths of these rag-tag insurgents to defeat the undead hordes and maybe - just maybe - bring real life back to Tyberia.' FROM games WHERE igdb_id = 164888 ON CONFLICT (game_id, language_code) DO NOTHING;
