INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ColorCube', 'A first-person 3D puzzle game. Objects of the same color cannot collide with each other, and you''re no exception. But not only you can change the color of yourself, but also you can change the color of other objects with a wand. This game has 43 levels. It takes about an hour to pass.' FROM games WHERE igdb_id = 208378 ON CONFLICT (game_id, language_code) DO NOTHING;
