INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Medieval Fantasy Survival Simulator', 'You''re gonna get yourself killed out here... There''s monsters, bandits, and much, much worse roaming these lands... Do you really think you''ve got what it takes to survive? Or do you think you''re cut out for much more than that... There''s only one way to find out, and time is of the essence!' FROM games WHERE igdb_id = 192525 ON CONFLICT (game_id, language_code) DO NOTHING;
