INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jumphobia: Homeward Bound', 'Jump, skip, hop and leap in Jumphobia: Homeward Bound, an indie sci-fi adventure game! Go as far as your little wheel can take you! Play as a little delivery bot from a far-flung future controlled by the monolithic "MARE" corporation, and find your way back home through the perilous deserts, dead forests, and untold wildlands that lie ahead.' FROM games WHERE igdb_id = 190170 ON CONFLICT (game_id, language_code) DO NOTHING;
