INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hunter A Hunter', 'Hunter A Hunter is an Action Horror Arena game inspired by Pacman. Instead of eating pills while hiding from ghosts with top-down view, Hunter A Hunter is you (as a sinner) playing first/third-person view to collect all lights scattered in arena while a hunter is searching for you.' FROM games WHERE igdb_id = 192461 ON CONFLICT (game_id, language_code) DO NOTHING;
