INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('k3lvn', 208793, '2022-07-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4yw9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1r2l.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'K3LVN', 'K3LVN is a sci-fi action platformer where the player is a creature who’s been experimented on and is trying to escape the space station lab where they’re being kept. K3LVN is able to change their state of matter to alter their behavior. The three states usable are the Gel state which is the default bipedal state, the Liquid state which makes K3LVN smaller and grants the ability to climb on certain walls, and the Solid State, which turns K3LVN into a ball to roll around and gain momentum. They must use these abilities in combination with each other to traverse the environment as quickly as possible.' FROM games WHERE igdb_id = 208793 ON CONFLICT (game_id, language_code) DO NOTHING;
