INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Malyshka', 'From the sunken depths of a quiet lake, your heart pulls you to the surface; a doll awaits your ghostly form on the shore. Who are you? Why are you here? Discover the sleepy town of Tikhiyavoda, its community, and most of all, yourself.' FROM games WHERE igdb_id = 188716 ON CONFLICT (game_id, language_code) DO NOTHING;
