INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'HordeCore', 'HordeCore is a kick-ass action side-scroller set in a post-apocalyptic world. Become the leader of an ever-expanding group of survivors. Manage supplies, upgrade your team, and craft deadly contraptions to defend yourself! Remember, exploration is vital in this harsh new world. Prepare to forge bizarre alliances and, together, face the many dangers of the wastelands. Take survival gameplay, combine it with base management, add RPG elements, and spice it up with a fully-fledged collectible card game - and you get HordeCore!' FROM games WHERE igdb_id = 112767 ON CONFLICT (game_id, language_code) DO NOTHING;
